public void init()
{
    ItemId              itemIdFilter;
    InventLocationId    inventLocationIdFilter;
    super();

    InventSum::queryAddSumFields(this.query().dataSourceTable(tableNum(InventSum)));
    if (caller1)
    {

        //helper = element.args().parmObject();
        itemIdFilter = caller1.parmItemId();
        inventLocationIdFilter = caller1.parminventoryLocationIdFilter();

        if (itemIdFilter || inventLocationIdFilter)
        {
            QueryBuildDataSource  qbds = this.queryBuildDataSource();
            qbds.addRange(fieldNum(METSalesOrderShipmentLoadHeader, Warehouse)).value(queryValue(inventLocationIdFilter));
            qbds.addRange(fieldNum(METSalesOrderShipmentLoadHeader, ShipmentStatus)).value(queryValue(enum2Str(MetShipmentStatus::Open)));
            qbds.addRange(fieldNum(METSalesOrderShipmentLoadHeader, ConfirmedShipDate)).value(queryRange(systemDateGet(), systemDateGet()+14));

            QueryBuildDataSource    qbds1 = qbds.addDataSource(tableNum(METSalesOrderShipmentLoadLines));
            qbds1.joinMode(JoinMode::InnerJoin);
            qbds1.addLink(fieldNum(METSalesOrderShipmentLoadHeader, ShipmentId), fieldNum(METSalesOrderShipmentLoadLines, ShipmentId));
            qbds1.addRange(fieldNum(METSalesOrderShipmentLoadLines, ItemId)).value(queryValue(itemIdFilter));
        }
    }


}

private PdsInventQty expQty()
{
    this.pdsNonNetExpiredBatch();

    return expQty;
}

private PdsInventQty nonNetQty()
{
    this.pdsNonNetExpiredBatch();

    return nonNetQty;
}

